def max_elements(p):
    if len(p) == 1:
        return 1
    max_len = 1
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            v = int(p[i] + p[j])
            if str(v) == p[i] + p[j]:
                remaining = p[:i] + p[i+1:j] + p[j+1:]
                max_len = max(max_len, 2 + max_elements(''.join(str(x) for x in remaining)))
    return max_len

