def max_elements(p):
    if len(p) == 1:
        return 1

    # Find the position to split the string into two parts
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            part1 = int(p[:i])
            part2 = int(p[j:])
            v = int(f"{part1}{part2}")
            if str(v) != p[i:j] + p[:i]:
                continue
            if part1 >= part2:
                return max(max_elements(str(part1)), max_elements(str(part2))) + 1
    return 1

